INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Что такое сборщик мусора (garbage collector)?',
    '**Сборщик мусора** - это механизм JVM, отвечающий за управление объектами в памяти. Программист выделяет память под объекты, поиском и очищением памяти от неиспользуемых объектов (объектов, на которые нет прямых или косвенных ссылок) занимается сборщик.

**Версия Java****GC по умолчанию****Примечания**Java 8Parallel GCОптимизирован для пропускной способности.Java 9G1G1 стал сборщиком по умолчанию, заменив Parallel GC.Java 10G1Улучшения в G1, включая параллельную полную сборку мусора.Java 11G1Введены ZGC и Shenandoah (экспериментальные).Java 12G1Улучшения в G1, включая возврат неиспользуемой памяти.Java 13G1Улучшения в ZGC и Shenandoah.Java 14G1ZGC и Shenandoah стали стабильными.Java 15G1ZGC стал кроссплатформенным.Java 16G1Улучшения в ZGC и Shenandoah.Java 17G1CMS окончательно удален.Java 21G1Введен Generational ZGC, улучшения в G1, ZGC и Shenandoah.**Когда использовать другие GC?**

- **ZGC** - для приложений с огромными кучами (терабайты) и требованиями к минимальным паузам (менее 10 мс).
- **Shenandoah** - для приложений с низкими задержками и большими кучами.
- **Parallel GC** - для приложений, где важна пропускная способность, а не низкие задержки.
- **Serial GC** - для однопоточных приложений или приложений с небольшими кучами.',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Java Core'
    ),
    8.33
);

