    gen_random_uuid(),
    'Что такое аннотация? Зачем нужна? Как создать свою аннотацию?',
    'Аннотация - это механизм пометки классов, методов и полей дополнительной информацией для компилятора, инструментов разработки и фреймворков

**Основные аннотации в Java**

АннотацияОписание`@Override`Проверяет, что метод переопределяет метод суперкласса.`@Deprecated`Отмечает метод/класс устаревшим, чтобы не использовать его в будущем.`@SuppressWarnings`Подавляет определенные предупреждения компилятора.`@FunctionalInterface`Показывает, что интерфейс является функциональным (с одним абстрактным методом).`@SafeVarargs`Подавляет предупреждения о небезопасных операциях с аргументами переменной длины (varargs).`@Native`Используется для констант, предназначенных для взаимодействия с нативным кодом.**Метаданные аннотаций (`Retention`, `Target`)**
Когда мы создаем свою аннотацию, важно понимать, как она будет использоваться. Это задается с помощью **мета-аннотаций**:

АннотацияОписание`@Retention`Определяет, на каком этапе жизненного цикла аннотация доступна (SOURCE, CLASS, RUNTIME).`@Target`Указывает, к чему можно применять аннотацию (методы, поля, классы и т. д.).`@Documented`Включает аннотацию в Javadoc.`@Inherited`Наследуется ли аннотация подклассами.`@Repeatable`Позволяет применять одну и ту же аннотацию несколько раз.**Как создать свою аннотацию?**

`import java.lang.annotation.*;

@Retention(RetentionPolicy.RUNTIME)

@Target(ElementType.METHOD)

@interface MyAnnotation {

String value();

int count() default 1;

}

class Example {

@MyAnnotation(value = "Hello", count = 3)

public void test() {

System.out.println("Метод с аннотацией");

}

}

`**Чтение аннотации с помощью рефлексии**

`import java.lang.reflect.Method;

public class Main {

public static void main(String[] args) throws Exception {

Method method = Example.class.getMethod("test");

MyAnnotation annotation = method.getAnnotation(MyAnnotation.class);

System.out.println("value: " + annotation.value());  // "Hello"

System.out.println("count: " + annotation.count());  // 3

}

}

`**Где используются аннотации в реальных проектах?**

Lombok, JUnit, Spring',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Java Core'
    ),
    4.17
);

