    'ClassLoader в Java',
    'ClassLoader (загрузчик классов) - это специальный компонент JVM, предназначенный для загрузки классов в память во время выполнения программы. Загружает классы, соблюдая иерархию и принцип делегирования.

Иерархия загрузчиков:

- Bootstrap - загружает базовые классы (`java.lang.*`, `java.util.*`)
- Platform (Extension до Java 9) - загружает модули платформы
- Application/System - загружает классы из classpath
- Custom - зависит от реализацииПринцип делегирования - перед тем как загрузить класс, загрузчик обращается в вышестоящему по иерархии и спрашивает, не загрузил ли он уже такой класс, чтобы не загружать класс дважды.',
