**LinkedList. Какая скорость добавления элемента в начало/середину/конец списка?**

Место добавленияСредняя сложностьХудшая сложностьПояснение**Начало списка**`O(1)``O(1)`Новый узел добавляется перед первым, переназначаются ссылки**Середина списка**`O(n)``O(n)`Требуется пройти список до нужного узла, после чего выполняется вставка**Конец списка**`O(1)``O(1)`Новый узел добавляется после последнего, переназначаются ссылки**LinkedList. Какая скорость удаления элемента в начале/середине/конце списка?**

