INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'ArrayList vs LinkedList',
    '**Критерий****ArrayList****LinkedList****Расположение в памяти**Последовательные блоки памяти (массив)Элементы связаны через указатели**Добавление в конец**O(1) (если есть место) или O(n) (при расширении)O(1)**Добавление в начало**O(n) (сдвиг всех элементов)O(1)**Добавление в середину**O(n) (сдвиг элементов)O(n) (поиск нужной позиции + изменение ссылок)**Удаление элемента**O(n) (сдвиг оставшихся элементов) или O(1) (удаление с конца)O(n) (поиск) или O(1) (если указатель известен)**Поиск по индексу**O(1)O(n) (идём по ссылкам)**Поиск по значению**O(n)O(n)**Память**Использует меньше памяти, т.к. хранит только данныеИспользует больше памяти, т.к. хранит ссылки**Где какой использовать?**
- **ArrayList** следует использовать, когда в приоритете доступ по индексу, так как эти операции выполняются за константное время. Добавление в конец списка в среднем тоже выполняется за константное время. Кроме того в ArrayList нет дополнительных расходов на хранение связки между элементами. Минусы в скорости вставки/удаления элементов находящихся не в конце списка, так как при этой операции все элементы правее добавляемого/удаляемого сдвигаются
- **LinkedList** удобен когда важнее быстродействие операций вставки/удаления, которые в LinkedList выполняются за константное время. Операции доступа по индексу производятся перебором с начала или конца (смотря что ближе) до нужного элемента. Дополнительные затраты на хранение связки между элементами.**Если часто вставляете/удаляете — выбирайте LinkedList, в противном случае ArrayList**

Преподаватель и сотрудник компании JetBrains Тагир Валеев на своих лекциях утверждает, что НЕ стоит использовать LinkedList, т.к. он не оптимизирован. Все задачи можно решить с такой же скоростью или быстрее используя ArrayList/ArrayDeque',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Коллекции'
    ),
    16.99
);

