INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Внутреннее устройство HashMap',
    'В **HashMap** бакет — это элемент массива, в котором хранятся записи (ключ-значение). Если у нескольких ключей совпадает хеш, их записи попадают в один бакет, где организуются в виде связного списка или сбалансированного дерева (в зависимости от Java версии).

***Сколько изначально бакетов создается?***

По умолчанию - **16**

***В каком случае количество бакетов увеличивается?***

- При попытке преобразовать список в дерево в таблице размером менее 64 бакетов
- Когда превышен порог загрузки (`size > threshold`).`threshold` вычисляется по формуле:

`threshold = capacity * loadFactor

`где `capacity` — это текущий размер таблицы бакетов, а `loadFactor` — это коэффициент загрузки (по умолчанию 0.75, то есть 75% от общего размера таблицы).

В таких случаях создается новая таблица размером в 2 раза больше текущего.

***Чтобы определить номер бакета есть формула. Какие в ней переменные?***

`bucketIndex = (hash & (capacity - 1));

`
- **`hash`** — хэш-код ключа, который возвращает метод `key.hashCode()`.
- **`capacity`** — текущая ёмкость таблицы (всегда степень двойки, например, 16, 32).
- **`bucketIndex`** — индекс бакета, в котором будет храниться элемент.Операция побитового `&` (AND) используется вместо `%`, так как она быстрее и эффективнее для степеней двойки.',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Коллекции'
    ),
    16.99
);

INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Что такое бакет? Внутреннее устройство бакета',
    '🗂️ Что такое бакет в HashMap?

**Бакет** — это элемент внутренней структуры `HashMap`, который используется для хранения пар **ключ-значение**.
Когда ты добавляешь элемент в `HashMap`, хеш-функция вычисляет **хеш-код ключа**, и на его основе определяется **индекс бакета**, куда будет помещён элемент.

⚙️ Внутреннее устройство HashMap и бакетов

- **Хеш-функция**: преобразует ключ в хеш-код.
- **Массив бакетов**: каждый элемент массива — это бакет.
- **Бакет**: может быть пустым или содержать одну или несколько пар ключ-значение.🧱 Структура бакета:

В Java (например), каждый бакет — это **связный список** или **дерево** (если слишком много коллизий).

`HashMap (массив бакетов)

│

├── Bucket[0] → null

├── Bucket[1] → Entry(key1, value1) → Entry(key2, value2)

├── Bucket[2] → Entry(key3, value3)

└── ...

`Если два ключа дают одинаковый хеш и индекс, они попадают в один бакет — это называется **коллизией**.

🌳 Когда бакет превращается в дерево?

В Java 8 и выше, если количество элементов в одном бакете превышает порог (обычно 8), связный список превращается в **красно-чёрное дерево** для ускорения поиска.

`Bucket[5] → Red-Black Tree

├── Entry(keyA, valueA)

├── Entry(keyB, valueB)

└── ...

`📊 Пример на Java:

`Map<String, String> map = new HashMap<>();

map.put("apple", "green");

map.put("banana", "yellow");

`
- `"apple"` → хеш-код → индекс бакета → вставка в бакет
- `"banana"` → другой хеш → другой бакет🧠 Итог:

ТерминЗначениеБакетЯчейка массива, куда попадают элементы с одинаковым хеш-индексомКоллизияСитуация, когда разные ключи попадают в один бакетEntryОбъект, содержащий ключ и значениеДерево в бакетеОптимизация при большом числе коллизий',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Коллекции'
    ),
    5.45
);

