INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Расскажите про принцип PECS',
    'Producer Extends, Consumer - Super:

- если мы объявили wildcard с `extends`, то это **producer**. Он только «продюсирует», предоставляет элемент из контейнера, а сам ничего не принимает
- если же мы объявили wildcard с `super`, то это **consumer**. Он только принимает, а предоставить ничего не можетДля совмещения обеих возможностей необходимо использовать конкретный тип, а не wildcard.

Альтернативным вариантом является применение паттерна wildcard capture.

На примере ниже для реверсирования коллекции с wildcard мы создаем обобщенный метод `rev`. Он объявлен с переменной типа `T`. Этот метод принимает список типов `T`, и мы можем сделать сет. При вызове метода `reverse(List<?> list)` в качестве аргумента передается список каких-то объектов (например, строк или целых чисел). Если мы можем захватить тип этих объектов и присвоить его переменной типа `X`, то можем заключить, что `T` является `X`.

`public static void reverse(List<?> list) {

rev(list);

}

private static <T> void rev(List<T> list) {

List<T> tmp = new ArrayList<>(list);

for (int i = 0; i < list.size(); i++) {

list.set(i, tmp.get(list.size()-i-1));

}

}

`',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Дженерики'
    ),
    4.49
);

