`Optional<String> getNestedValue(Optional<Optional<String>> nestedOpt) {

return nestedOpt.flatMap(opt -> opt);

}

`Использовать `map`, если функция возвращает нужный вам объект, или `flatMap`, если функция возвращает `Optional` объект',
