INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Что такое стирание типов (Type Erasure) в Java Generics',
    'JVM не хранит информацию о параметризованных типах в рантайме. Все операции с дженериками преобразуются в операции с “сырыми типами” (raw types) на этапе компиляции (стирание типов)

**Что такое стирание типов?**

Стирание типов (Type Erasure) - процесс, при котором информация о дженериках удаляется во время компиляции. JVM видит только “сырой” тип

**Generics. Можно ли получить тип в рантайме?**

В общем случае нет. В Java используется **стирание типов** (Type Erasure), что означает, что информация о параметризованных типах удаляется после компиляции. На этапе выполнения JVM работает только с “сырыми типами”

**Исключение:** Можно сохранить информацию о типах с помощью рефлексии или через использование классов-обёрток

Пример с `TypeToken`:

`import java.lang.reflect.Type;

import com.google.gson.reflect.TypeToken;

Type type = new TypeToken<List<String>>(){}.getType();

System.out.println(type); // java.util.List<java.lang.String>

`Табличка терминов по теме

**Термин****Расшифровка**Дженерик-типы (generic types)Дженерик-класс или дженерик-интерфейс с одним или несколькими параметрами в заголовкеПараметризованный тип (parameterized types)Вызов дженерик-типа. Для дженерик-типа `List<E>` параметризованным типом будет, например, `List<Integer>`Параметр типа (type parameter)Используются при объявлении дженерик-типов. Для List`<E>` E - это параметр типаАргумент типа (type argument)Тип объекта, который может использоваться вместо параметра типа. Например, для List`<Integer>` `Integer` - это аргумент типаWildcardОбозначается символом «?» - неизвестный типОграниченный wildcard (bounded wildcard)Ограниченный сверху `<? extends Citrus>` снизу - `<? super Orange>`Сырой тип (raw type)Имя дженерик-типа без аргументов типа. Для `List<E>` сырой тип - это `List`Универсальный параметр`<T>`, `<E>` и т.д. в объявлении классов, интерфейсов, методов',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Дженерики'
    ),
    3.53
);

