VALUES (
    gen_random_uuid(),
    'Что такое лямбда выражение? Чем его можно заменить?',
    'Лямбда-выражение - это сокращённая запись анонимного класса, реализующего функциональный интерфейс.

**Чем его можно заменить?**

- Анонимным классом
- Обычным классом, реализующим интерфейс
- Ссылкой на метод (method reference)**Анонимный класс vs лямбда**

Это два способа реализации интерфейсов или создания компактного кода в Java. Они имеют сходства, но различаются по способу использования, синтаксису и некоторым ограничениям

**Анонимный класс** - это локальный класс без имени, который объявляется и создаётся одновременно

**Лямбда** - это краткий способ объявления реализации функционального интерфейса

**Критерий****Анонимный класс****Лямбда-выражение****Синтаксис**Более громоздкийКраткий и лаконичный**Совместимость**Любой интерфейс или классТолько функциональный интерфейс**Использование `this`**Ссылается на экземпляр анонимного классаСсылается на экземпляр внешнего класса**Многометодные интерфейсы**Можно переопределять несколько методовНе поддерживается (только один метод)**Поддержка переменных**Может содержать свои переменные и методыНе может содержать свои методы или поля**Производительность**Более ресурсоёмкий (создаёт новый класс)Оптимизирован JVM (не создаёт новый объект класса)',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Функциональные интерфейсы'
    ),
    7.37
);

