VALUES (
    gen_random_uuid(),
    'Что такое синхронизация? Какие способы синхронизации существуют в Java?',
    'Синхронизация (потоков) - это механизм координации доступа нескольких потоков с целью предотвратить Race Condition и обеспечить согласованность памяти. Достигается через блокировки и области видимости

**Системная синхронизация**

В Java оператор `synchronized(obj)` привязывает блок кода к определённому потоку, захватывая монитор объекта `obj` и исключая доступ к нему других потоков в этот момент. Если этот поток должен ожидать выполнения каких-то условий, то он должен вызвать у `obj` метод `wait()` - работа потока приостанавливается (он “засыпает”), он отпускает захваченный монитор.

Другой поток может вызвать на этом же объекте метод `notify()`, предварительно захватив его монитор, в результате чего ждущий на `obj` поток «просыпается» и продолжает своё выполнение

**ВАЖНО**:

- методы `wait()` и `notify()` не синхронизированы, поэтому их можно вызвать только внутри `synchronized`-блока. В противном случае в рантайме будет выброшено `IllegalMonitorException: current thread is not owner`
- после вызова `notify()` спящий поток “просыпается” не ранее, чем поток, вызвавший `notify()` , выйдет из блока synchronized (т.е. только после того, как им будет отпущен монитор)`public class Counter {

private int count;

public synchronized void increment() {

count++;

}

}

эквивалентно

public class Counter {

private int count;

public void increment() {

synchronized (this) {

count++;

}

}

}

`Особенности `syncronized` в зависимости от места объявления:

- блок кода - необходимо явно указывать объект синхронизации в круглых скобках
- нестатический метод - синхронизация на экземпляре (`this`)
- статический метод - синхронизация на объекте класса (`ClassName.class`), т.е. синхронизация происходит на уровне класса и распространяется на все экземпляры**Метод `Thread.join()`**

Поток вызвавший этот метод будет ждать до тех пор, пока объект, у которого был вызван этот метод не закончит свое выполнение

`public static void main(String[] args) {

SimpleThread simpleThread = new SimpleThread();

simpleThread.start();

try {

simpleThread.join(); //До тех пор, пока этот поток не завершит свою работу - мы не пойдем дальше

} catch (InterruptedException e) {

throw new RuntimeException(e);

}

System.out.println(Thread.currentThread().getName());

}

`**Классы из пакета `java.util.concurrent`**

`ReentrantLock`, `Semaphore`, `CyclicBarrier`. Концепция данного подхода заключается в использовании атомарных операций и переменных',
