VALUES (
    gen_random_uuid(),
    'Как работать с коллекциями в многопоточном программировании?',
    '- Превратить обычную коллекцию в синхронизированную, с помощью Collections.synchronized()

`List<String> list = Collections.synchronizedList(new ArrayList<>())`
- Использование Concurrent-коллекций`CopyOnWriteArrayList`, `CopyOnWriteArraySet`
- Неблокирующие хеш-таблицы (`ConcurrentHashMap`, `ConcurrentSkipListMap`, ConcurrentSkipListSet`)`
- Неблокирующие очереди (`ConcurrentLinkedQueue` и `ConcurrentLinkedDeque`)**Почему мы должны использовать потокобезопасные коллекции?**

Когда несколько потоков одновременно обращаются к одной и той же коллекции, возможно возникновение **состояния гонки (race condition)**, приводящих к следующим проблемам:

- **искажение данных** - одновременная модификация может нарушить целостность данных
- **исключения** - например, `ConcurrentModificationException`, когда один поток перебирает коллекцию, а другой изменяет её структуру
- **непредсказуемое поведение** - результат работы программы становится нестабильным**CopyOnWriteCollections. Что это? Как происходит запись?**

Это потокобезопасные коллекции (`CopyOnWriteArrayList`, `CopyOnWriteArraySet`). Как происходит запись:

- При добавлении элемента создается копия всей коллекции с добавленным изменением
- После завершения операции, оригинальная коллекция заменяется на новую копию, а все другие потоки продолжают работать со старой версией, пока новая не станет доступной

*Прим.: стоит использовать, когда в программе много операций чтения***ConcurrentHashMap. Что это? Как происходит запись?**

Это потокобезопасная реализация хеш-таблицы. Как происходит запись:

- хеширование ключа - сначала вычисляется хеш-код ключа, что бы определить, в какой бакет хеш-таблицы попадет этот элемент
- блокировка бакета - блокируется только тот бакет, в который будет добавлен элемент (если бакет пустой, то применяется CAS-вставка без блокировки)
- добавление элемента - элемент добавляется, блокировка с бакета снимается*Прим*.: *на самом деле блокируется не бакет (т.к. это вообще абстракция), а первый его элемент*

*Прим.2: до Java 8 ConcurrentHashMap делил внутреннюю таблицу на сегменты (Segment[]). Каждый сегмент представлял собой небольшую хэш-таблицу с отдельной блокировкой (ReentrantLock). Когда поток записывал данные, блокировался только сегмент, содержащий нужный ключ. Это позволяло нескольким потокам одновременно работать с разными сегментами. Устаревший механизм сегментов усложнял архитектуру и ограничивал параллелизм, поэтому был упразднён.*',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Многопоточность'
    ),
    5.13
);

