    'Расскажи про пакет concurrent',
    'Пакет `java.util.concurrent` предоставляет набор инструментов для работы с многопоточностью. Основные компоненты:

- **Executor и ExecutorService** - используются для управления потоками и выполнения задач. ExecutorService позволяет управлять пулом потоков
- **Синхронизированные коллекции** - потокобезопасные коллекции, такие как:`ConcurrentHashMap`
- `CopyOnWriteArrayList`
- `BlockingQueue`
- **Locks** - более гибкая альтернатива синхронизированным блокам:`ReentrantLock` - предоставляет явное управление блокировками + реентрабельный
- `ReadWriteLock` - разделяет блокировки чтения и записи
- **Синхронизаторы** - объекты для координации потоков:`Semaphore` - ограничение количества одновременно выполняющихся потоков
- `CountDownLatch` - дословно «защёлка с обратным отсчетом» - остановка потоков, пока внутренний счётчик не станет равен нулю
- `CyclicBarrier` - синхронизация нескольких потоков (обратен семафору, останавливает выполнение, пока в точку не придёт определённое количество потоков)
- `Exchanger` - обмен данными между **двумя** потоками
- **Future и CompletableFuture**`Future` - используется для получения результата выполнения асинхронной задачи
- `CompletableFuture` - удобный способ построения асинхронных цепочек из результатов, поддерживает декларативный стиль программирования',
