VALUES (
    gen_random_uuid(),
    'Что такое CAS операции? (Compare And Swap)',
    '**CAS (Compare And Swap)** — атомарная операция, которая используется для управления многопоточным доступом к данным без использования блокировок

- **Принцип работы:**Проверяется, соответствует ли текущее значение ожидаемому
- Если да, то происходит обновление значения
- Если нет, операция повторяется
- **Этапы:**Сравнение текущего значения с ожидаемым
- Обновление значения, если они совпадают
- **Особенности:**Обеспечивает высокую производительность, так как не требует блокировок
- Используется в `Atomic` классах и потокобезопасных коллекциях (`ConcurrentHashMap`)Пример работы CAS

`AtomicInteger atomicInteger = new AtomicInteger(0);

int expectedValue = 0;

int newValue = 1;

// CAS-операция

boolean result = atomicInteger.compareAndSet(expectedValue, newValue);

System.out.println(result); // true, если значение обновлено

`',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Многопоточность'
    ),
    3.21
);

