VALUES (
    gen_random_uuid(),
    'ForkJoinPool vs FixedThreadPool',
    '**Фреймворк Fork/Join**, представленный в JDK 7, - это набор классов и интерфейсов, позволяющих использовать преимущества многопроцессорной архитектуры современных компьютеров. Он разработан для выполнения задач, которые можно рекурсивно разбить на маленькие подзадачи, которые можно решать параллельно

- **Этап Fork** - большая задача разделяется на несколько меньших подзадач, которые в свою очередь также разбиваются на меньшие. И так до тех пор, пока задача не становится тривиальной и решаемой последовательным способом
- **Этап Join** - далее (опционально) идет процесс «свертки» - решения подзадач некоторым образом объединяются, пока не получится решение всей задачиЕще одно преимущество этого фреймворка заключается в том, что он использует **work- stealing** алгоритм: потоки, которые завершили выполнение собственных подзадач, могут «украсть» подзадачи у других потоков, которые всё ещё заняты

`import java.util.concurrent.*;

class SumTask extends RecursiveTask<Integer> {

private final int[] array;

private final int start, end;

SumTask(int[] array, int start, int end) {

this.array = array;

this.start = start;

this.end = end;

}

@Override

protected Integer compute() {

if (end - start <= 2) {

return array[start] + array[end - 1]; // Базовый случай

}

int mid = (start + end) / 2;

SumTask leftTask = new SumTask(array, start, mid);

SumTask rightTask = new SumTask(array, mid, end);

leftTask.fork();

return rightTask.compute() + leftTask.join();

}

}

public class ForkJoinExample {

public static void main(String[] args) {

ForkJoinPool pool = new ForkJoinPool();

int[] numbers = {1, 2, 3, 4, 5, 6, 7, 8};

int sum = pool.invoke(new SumTask(numbers, 0, numbers.length));

System.out.println("Сумма: " + sum); // 36

}

}

`Свойство`ForkJoinPool``FixedThreadPool`**Размер пула**Автоматически настраиваетсяФиксированное число потоков**Поддержка work-stealing?**ДаНет**Когда использовать?**Рекурсивно разделяемые задачи (`RecursiveTask`)Независимые (`Runnable`, `Callable`)',
