    'NoSQL vs SQL',
    '- SQL (реляционные базы данных) - структурированные таблицы с чёткой схемой данных.
- NoSQL (нереляционные базы данных) - гибкая структура для неструктурированных или полуструктурированных данных.**Критерий****SQL (реляционные)****NoSQL (нереляционные)**Структура данныхТаблицы (строки и столбцы)Документы, ключ-значение, графы, колонкиСхемаЖёсткая, требуется заранее определитьГибкая, можно изменять структуру данныхЯзык запросовSQL (стандартный язык запросов)API или специальные запросы (например, MongoDB Query)Предпочтительный тип масштабированияВертикальный (добавление ресурсов серверу). Горизонтальное сложно в связи с жёсткой структуройГоризонтальный (добавление серверов), хотя и вертикальный не доставляет больших проблемЦелостность данныхВысокая (ACID-транзакции)Может быть слабее, иногда поддерживается BASEСкоростьОптимизировано для сложных операций и JOINВысокая скорость для простых операцийКогда использоватьСтруктурированные данные, сложные связиГибкие, быстро меняющиеся данныеПримерыMySQL, PostgreSQL, OracleMongoDB, Redis, Cassandra, Neo4jACID - это классический подход к управлению транзакциями в реляционных базах данных, который обеспечивает высокий уровень согласованности и надежности данных. ACID-транзакции являются “жёсткими”, так как они гарантируют, что транзакция либо полностью выполнится, либо откатится к исходному состоянию в случае сбоя, что обеспечивает согласованность данных

BASE - более гибкий подход, который учитывает ограничения и неизбежность ошибок в распределенных системах. BASE поддерживает высокую доступность и отказоустойчивость путем снижения требований к согласованности данных. Это достигается за счет того, что база данных может находиться в промежуточном состоянии - состоянии, когда некоторые копии данных могут быть обновлены, а другие нет. Однако, с течением времени все копии данных сходятся к одному состоянию (eventually consistent), что обеспечивает согласованность.

- **B**asic **A**vailability - система отвечает на любой запрос, но этот ответ может быть содержать ошибку или несогласованные данные
- **S**oft-state - состояние системы может меняться со временем из-за изменений конечной согласованности
- **E**ventual consistency (конечная согласованность) - система, в конечном итоге, станет согласованной. Она будет продолжать принимать данные и не будет проверять каждую транзакцию на согласованностьТаким образом, основная разница между BASE и ACID заключается в том, что ACID обеспечивает жесткую согласованность данных, в то время как BASE обеспечивает гибкую согласованность, позволяющую достичь высокой доступности и отказоустойчивости данных в условиях распределённости и масштабируемости.',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Базы данных'
    ),
    5.13
);

