VALUES (
    gen_random_uuid(),
    'Уровни изолированности (read uncommitted, read committed, repeatable read, serializable)',
    'От менее строгого к самому строгому:

- Read uncommited (незащищённое чтение) - транзакции могут читать данные, которые еще не зафиксированы другими транзакциями (использовать, когда все транзакции на чтение)
- Read commited (защищённое чтение) - транзакции могут читать только те данные, которые уже зафиксированы другими данными (решает потерянное обновление и грязное чтение)
- Repeatable read (повторяющееся чтение) - в рамках одной транзакции многократный запрос данных всегда возвращает одинаковый набор данных, независимо от изменений, сделанных другими транзакциями (решает потерянное обновление, грязное чтение и неповторяющееся чтение)
- Serializable - самый строгий уровень изоляции. Транзакции выполняются так, как будто происходят последовательно одна за другой (решает всё, но бьёт по производительности)**Какой уровень изолированности стоит по умолчанию в MySQL?**

В MySQL - Repeatable read, в PostgreSQL - Read commited

**Зависимость скорости работы БД и уровня изоляции**

**Уровень изоляции****Описание****Влияние на производительность**Read UncommittedТранзакции могут читать данные, которые ещё не зафиксированыСамый быстрый, но данные могут быть неконсистентнымиRead CommittedТранзакции читают только зафиксированные данныеСредняя производительность, баланс между скоростью и консистентностьюRepeatable ReadГарантирует, что данные, прочитанные транзакцией, не изменятся, пока транзакция не завершенаСнижает производительность из-за блокировок, но обеспечивает более высокую консистентностьSerializableСамый высокий уровень изоляции, предотвращает все виды аномалийСамый медленный, так как использует полные блокировки',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'SQL'
    ),
    24.68
);

