INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Индексы в SQL. Что это?',
    'Индексы в БД - это инструмент оптимизации/ускорения запросов путём создания упорядоченного набора указателей на строки таблицы. Ускорение происходит за счёт того, что структура индекса оптимизирована под поиск (например, b-tree). При этом, чем больше дубликатов в столбце - тем хуже работает индекс

**В индексе ссылка на данные или в самом индексе кешируем данные?**

В индексе хранятся **ссылки** на реальные данные, которые находятся в таблице базы данных. Эти ссылки могут быть представлены в виде:

- **указателей на строки** в таблице, где хранятся данные
- **идентификаторов записей**, которые позволяют найти данные в таблицеВ Postgres в индексе хранятся **ссылки** на реальные данные, которые находятся в таблице базы данных. Например, в **B-tree**:

- промежуточные узлы дерева содержат только **ключи** для направления поиска
- в листьях дерева хранятся не сами данные, а **ссылки на данные** в таблице (или другие индексы)Однако, можно создать покрывающий индекс - индекс, который включает не только ключи, но и значение колонки(ок). Такие индексы позволяют извлекать данные не обращаясь к таблице. Пример:

`CREATE INDEX idx_price ON products(price) INCLUDE (name);

-- Теперь индекс хранит значения price + колонку name, что позволяет выполнить запрос

SELECT price, name FROM products WHERE price > 50;

-- не обращаясь к таблице

`В MySQL (InnoDB) поведение индексов отличается в зависимости от их типа:

- PRIMARY KEY (кластерный индекс) - индекс содержит сами данные
- Обычный (SECONDARY INDEX) индекс хранит ссылки (ключи PRIMARY KEY) на данные**Какие индексы по умолчанию в разных СУБД?**

По-умолчанию в большинстве CУБД стоит B-tree

**Сравнение сложности поиска**

**Тип поиска****Структура****Сложность****Когда применять?****Без индекса**Полный перебор`O(N)`Маленькие таблицы**B-Tree индекс**Сбалансированное дерево`O(log N)`Частый поиск по диапазонам**Hash-индекс**Хеш-таблица`O(1)`Быстрый поиск по `=`**Как добавить новый индекс в большую, активно используемую таблицу в продакшене, не блокируя доступ и не приостанавливая работу приложения, и какие стратегии можно применить для минимизации влияния на систему?**

- **PostgreSQL** - `CREATE INDEX CONCURRENTLY` / pg_repack / gh-ost
- **MySQL** - `ALTER TABLE … ALGORITHM=INPLACE, LOCK=NONE` / pt-online-schema-change**Как определить, какой индекс будет использован в запросе с фильтрацией по столбцу с низкой селективностью (например, пол), и как селективность влияет на эффективность индексов?**

- **EXPLAIN ANALYZE** покажет, будет ли `Index Scan` или `Seq Scan`
- **pg_stats.n_distinct** даёт оценку числа уникальных значений',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'SQL'
    ),
    19.87
);

