    'Какие виды индексов знаешь?',
    '**Тип индекса****Описание****Использование**B-дерево (B-tree)Стандартный индекс, используемый в большинстве СУБД. Данные хранятся в сбалансированном деревеДля поиска, сортировки, диапазонных запросовХеш-индекс (Hash Index)Использует хеш-функцию для поиска точных совпаденийДля быстрого поиска по уникальным значениям (например, ID)Индекс с несколькими столбцами (Composite Index)Индекс, включающий несколько столбцов. Ускоряет запросы, использующие несколько фильтровКогда запросы фильтруют по нескольким столбцам одновременноИндекс с уникальными значениями (Unique Index)Индекс, обеспечивающий уникальность значений в столбцеДля обеспечения уникальности значений (например, email)Индекс полного текста (Full-Text Index)Индекс для быстрого поиска по тексту, включая ключевые слова и фразыПоиск по длинным текстовым полям, например, в статьях или документахИндекс обратного списка (Bitmap Index)Индекс с битовыми картами для колонок с малым числом уникальных значенийДля столбцов с ограниченным числом уникальных значений, например, полИнкрементный (Clustered Index)Индекс, при котором данные таблицы физически упорядочены в соответствии с индексомКогда необходимо хранить данные в порядке индекса, например, по IDИндекс по выражению (Functional Index)Индекс, основанный на вычисленных значениях или функциях над столбцамиДля запросов, использующих функции или выражения в фильтрахИндекс на основе дерева (GiST — Generalized Search Tree)Общий тип дерева, используемый для индексации сложных типов данныхДля индексации географических данных или других сложных типовИндекс на основе префикса (Prefix Index)Индекс, созданный на части строки, например, на первых символахДля текстовых полей, где важно индексировать только часть строки (например, первые несколько символов)GIN (Generalized Inverted Index)Инвертированная структура: GIN создает карту, связывающую значения (ключи) с идентификаторами строк (TID), в которых эти значения встречаются. B-tree под капотомИдеален для`JSONB` (операторы `@>`, `?`), `ARRAY` (операторы `<@`, `@>`, `&&`)Покрывающий индекс (Covering Index)Схож с композитным, но INCLUDE-колонки не участвуют в поиске/фильтрацииCREATE INDEX idx_users_coverON users(email)INCLUDE(name, age)Для определённого набора часто запрашиваемых полей, не участвующих в фильтрации',
