INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Проблема N + 1. Способы решения проблемы',
    'Это проблема, которая возникает при ленивой загрузке сущности из БД, когда вместо одного запроса, включающего основную сущность и все зависимые, происходит один запрос для основной сущности и N запросов для зависимых сущностей

**Пример:**

Есть две связанные сущности: User (пользователь) и Order (заказ). Каждый пользователь может иметь много заказов

Допустим, нужно получить список всех пользователей и их заказов. Проблема N+1 возникает, когда вместо одного запроса к базе данных для получения всех пользователей и их заказов приложение сначала делает 1 запрос, чтобы получить всех пользователей, а затем делает N дополнительных запросов - по одному для каждого пользователя, чтобы получить его заказы

`@Entity

public class User {

@Id

private Long id;

private String name;

@OneToMany(mappedBy = "user", fetch = FetchType.LAZY)

private List<Order> orders;

}

@Entity

public class Order {

@Id

private Long id;

private String item;

@ManyToOne

@JoinColumn(name = "user_id")

private User user;

}

`
**Как избежать проблемы N + 1**

- JOIN FETCH. Это способ сказать Hibernate загрузить связанные данные вместе с основными (типа обычного JOIN-а). Нюансы:Необходимо использовать `DISTINCT`, чтобы избежать дубликатов (из-за JOIN с коллекцией будет происходить декартово произведение - для каждой связанной сущности будет добавлена главная сущность)
- Не работает с пагинацией (`setFirstResult`, `setMaxResults`), если используется `JOIN FETCH` с коллекцией`@Query("SELECT DISTINCT u FROM User u JOIN FETCH u.orders")

List<User> findAllUsersWithOrders();

`
- Использовать EntityGraph. Указываем, какие данные загружать в конкретных запросах, не изменяя сущности (как в случае с жадной загрузкой)`@EntityGraph(attributePaths = {"orders"})

List<User> findAll();

`
- Использовать **`FetchMode.SUBSELECT`** - загружает все коллекции одним подзапросом при первом обращении`    @OneToMany(mappedBy = "user", fetch = FetchType.LAZY)

@Fetch(FetchMode.SUBSELECT)

private List<Order> orders;

``Транслируется в``SELECT * FROM order WHERE user_id IN (SELECT id FROM user)

`
- Использовать пакетную загрузку - `@BatchSize` позволяет загружать связанные сущности пачками

```java

private List books;

@OneToMany(mappedBy = “user”, fetch = FetchType.LAZY)

@BatchSize(size = 50)

private List orders;`Для 100 заказов Hibernate выполнит 2 запроса:``SELECT * FROM order WHERE user_id IN (?, ?, ..., ?) // 50 ID

SELECT * FROM order WHERE user_id IN (?, ?, ..., ?) // Оставшиеся 50 ID`
- Использовать `FetchType.EAGER` вместо `FetchType.LAZY`',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'ORM'
    ),
    20.51
);

