    'Связи между таблицами в ORM',
    '- OneToOne - один экземпляр сущности может быть связан не больше чем с одним экземпляром другой сущности
- OneToMany - одна сущность может ссылаться ко многим сущностям
- ManyToOne - несколько сущностей может ссылаться к одной сущности
- ManyToMany - много сущностей могут относится ко многим сущностям.**Bidirectional** (с использованием MappedBy) - ссылка на связь устанавливается у всех сущностей, т.е. в сущности 1 будет ссылка на сущность 2 и наоборот. Сущность 1 будет владельцем этой связи (важно при каскадном удалении)
- **Unidirectional** - ссылка на связь устанавливается только у одной стороны**Как реализована связь OneToMany?**

Одному объекту одной сущности соответствует множество объектов другой сущности

`@Entity

public class Department {

@Id @GeneratedValue

private Long id;

@OneToMany(mappedBy = "department", cascade = CascadeType.ALL)

private List<Employee> employees;

}

@Entity

public class Employee {

@Id @GeneratedValue

private Long id;

@ManyToOne

private Department department;

}

`**Как реализована связь ManyToOne?**

Множеству объектов одной сущности соответствует один объект другой сущности

`@Entity

public class Employee {

@Id @GeneratedValue

private Long id;

@ManyToOne

@JoinColumn(name = "department_id")

private Department department;

}

@Entity

public class Department {

@Id @GeneratedValue

private Long id;

}

`**Как реализована связь ManyToMany?**

Для реализации такого вида связи создается промежуточная таблица для хранения идентификаторов обеих сущностей

**Пример**: учителя могут преподавать несколько предметов, каждый предмет может преподаваться несколькими преподавателями

`@Entity

public class Student {

@Id @GeneratedValue

private Long id;

@ManyToMany

@JoinTable(

name = "student_course",

joinColumns = @JoinColumn(name = "student_id"),

inverseJoinColumns = @JoinColumn(name = "course_id")

)

private List<Course> courses;

}

@Entity

public class Course {

@Id @GeneratedValue

private Long id;

@ManyToMany(mappedBy = "courses")

private List<Student> students;

}

`**Тип связи****Суть****Пример отношений****Особенности****Реализация в базе данных**OneToOneОдин к одномуПаспорт и владелецКаждая сущность связана с одной другой сущностьюОдин из объектов содержит внешний ключOneToManyОдин ко многимДепартамент и сотрудникиОдин объект связан с несколькими объектами другой сущностиОдин внешний ключ на стороне “многих”ManyToOneМногие к одномуСотрудники и департаментОбратное отношение к `OneToMany`Внешний ключ на стороне “многих”ManyToManyМногие ко многимСтуденты и курсыМножеству объектов одной сущности соответствует множество другойПромежуточная таблица**OneToMany: разница между List и Set**

**Характеристика**`List``Set`УникальностьДопускает дубликатыГарантирует уникальность элементовПорядокСохраняет порядок добавленияНе гарантирует порядокПроизводительностьМедленнее при проверке наличияБыстрее при проверке наличияИспользуемая реализация`ArrayList` или `LinkedList`Обычно `HashSet` или `TreeSet`**Что такое `Cascade`?**

`Cascade` в JPA определяет, что делать с зависимыми объектами при изменении основного объекта.

**Пример:**

`@Entity

class Parent {

@Id @GeneratedValue

private Long id;

@OneToMany(mappedBy = "parent", cascade = CascadeType.ALL)

private List<Child> children;

}

@Entity

class Child {

@Id @GeneratedValue

private Long id;

@ManyToOne

@JoinColumn(name = "parent_id")

private Parent parent;

}

`Если удалить `Parent`, то все `Child` объекты тоже удалятся.

**Тип****Описание**`ALL`Применяет все виды каскада (`PERSIST`, `REMOVE`, `MERGE`, `REFRESH`, `DETACH`)`PERSIST`Автоматически сохраняет зависимые сущности`REMOVE`Удаляет зависимые сущности`MERGE`Обновляет зависимые сущности`REFRESH`Перезаписывает зависимые сущности из БД`DETACH`Удаляет зависимые сущности из контекста (но не из БД)**Плюсы:**

- Упрощает работу с зависимыми объектами
- Автоматизирует `save()` и `delete()`
- Уменьшает количество `EntityManager` вызовов**Минусы:**

- Может неожиданно удалить важные данные (`REMOVE` без проверки)
- `ALL` может привести к непредвиденным каскадным операциям
- Может нагружать базу данных, если слишком много зависимостей',
