    'Hibernate. Что хранится в Persistence Context? Сколько времени объект хранится в Persistence Context?',
    '**Persistence Context** (контекст персистентности) - это механизм Hibernate, который управляет состоянием сущностей (entities) в рамках сессии (Session). Он отслеживает изменения в сущностях и синхронизирует их с базой данных. Persistence Context можно рассматривать как кэш первого уровня, который существует на протяжении жизни сессии.

В Persistence Context хранятся:

- **Управляемые сущности (Managed Entities)**:это объекты, которые были загружены в текущую сессию (например, с помощью `session.get()`, `session.load()`, или через запросы `HQL`, `Criteria API`)
- Hibernate отслеживает изменения в этих объектах и автоматически синхронизирует их с базой данных при коммите транзакции
- **Сущности, добавленные для сохранения**:объекты, которые были добавлены в Persistence Context с помощью `session.save()`, `session.persist()`, или `session.update()`
- **Сущности, помеченные на удаление**:объекты, которые были помечены на удаление с помощью `session.delete()`
- **Снимки состояния (Snapshots)**:Hibernate сохраняет снимки состояния сущностей на момент их загрузки. Эти снимки используются для определения изменений в объектах и генерации соответствующих SQL-запросов при синхронизации с базой данных
- **Идентификаторы сущностей**:Persistence Context хранит идентификаторы (ID) всех управляемых сущностей, чтобы быстро находить их в кэше**Сколько времени объект хранится в Psersistence Context?**

- До окончания сессии
- До явного удаления (`evict` или `clear`)
- До того, как объект переходит в состояние `detached`',
