- **Неявное смешение слоёв** - Внедрение контекста или провайдера в бизнес-код может затруднить тестирование
- **Множественные реализации** - если есть несколько `MyPrototypeBean` (например, `FastPrototype`, `SlowPrototype`), нужно уточнять:`public MySingletonService(

@Qualifier("fastPrototypeBean") ObjectProvider<MyPrototypeBean> fastProvider) { … }

`
- **Уничтожение prototype-бинов** - контейнер сам не вызывает `@PreDestroy` у prototype-бинов. Если в них есть ресурсы, придётся очищать вручную
- **Прокси и AOP** - при использовании `proxyMode` методы, помеченные `final` или `private`, не проксируются. Это может ломать логику
- **Сериализация** - если singleton-бин сериализуется, прокси-ссылки на prototype-бин могут привести к проблемам при десериализации',
