VALUES (
    gen_random_uuid(),
    'Жизненный цикл Bean. Вопросы связанные с классами, входящими в жизненный цикл бина',
    'Spring управляет созданием, инициализацией и уничтожением бинов в рамках контейнера IoC. Этот жизненный цикл можно разделить на несколько этапов

- **Парсинг конфигураций, сканирование аннотаций и создание BeanDefinition**

Spring (BeanDefinitionReader) ищет классы, которые помечены аннотациями, указывающими на то, что они являются бинами (или содержат таковые). Эти аннотации включают:

`@Component`, `@Service`, `@Repository`, `@Controller`, `@Configuration`

Spring сканирует классы в пакетах, указанных в аннотации `@ComponentScan`, или в пакете, где находится класс с аннотацией `@SpringBootApplication`. Найденные классы парсятся, и для них создаются BeanDefinition

`BeanDefinition` - это специальный интерфейс, через который можно получить доступ к метаданным будущего бина. В зависимости от конфигурации будет использоваться тот или иной механизм парсинга конфигурации. Все они складываются в `ConcurrentHashMap`, в которой ключ - имя бина, а объект сам `BeanDefinition`. При старте приложения в IoC контейнер попадут бины, которые имеют скоуп синглтон, а остальные создадутся тогда, когда они нужны. Сначала регистрируются все `@Configuration` для дальнейшего парсинга
- **Настройка созданных BeanDefinition**

Есть возможность повлиять на бины до их создания. Для этого существует интерфейс `BeanFactoryPostProcessor`, реализовав который, получаем доступ к созданным `BeanDefinition` и можем их изменить при помощи метода `postProcessBeanFactory`.
- **Создание экземпляра бинов**

Сначала из мапы c `BeanDefinition`-ами достаются бины, необходимые для настройки других бинов, а потом остальные (рекурсивное разрешение зависимостей). Созданием занимается `BeanFactory` (вызывает конструкторы), но можно и делегировать это фабрике, реализующей интерфейс `FactoryBean`
- **Внедрение зависимостей (через поля и сеттеры)**
- **Настройка созданных бинов**

Бины уже созданы, их можно донастроить. Интерфейс `BeanPostProcessor` позволяет вклиниться в процесс настройки бинов до того, как они попадут в контейнер. Контекст автоматически обнаруживает бины реализующие этот интерфейс и помечает их. Есть два метода

`postProcessBeforeInitialization` вызывается до init метода
- `postProcessAfterInitialization` - послеСначала сработает метод `postProcessBeforeInitialization()` всех имеющихся `BeanPostProcessor`-ов. Затем, при наличии, будет вызван `init`-метод.

В спринге если какой-то из `BeanPostProcessor` что-то меняет в классе (в т.ч. добавляет проксирование), он должен делать это на этапе после `init`. Следовательно, `init` всегда работает на оригинальный метод до проксирования.

В конце бины пройдут через `postProcessAfterInitialization()`.

`_Примечание: если бин имплементирует_ `InitializingBean`_, то Spring вызовет метод_ `afterPropertiesSet()` _перед init-методом. Интерфейс не рекомендуется к использованию как устаревший_`
- **Бины созданы** На этом этапе их можно получить с помощью метода `ApplicationContext.getBean()`
- З**акрытие контекста**

Когда контекст закрывается, бин уничтожается. Если в бине есть `@PreDestroy` метод, то перед уничтожением бина он вызовется. Если в `@Bean` определён метод destroyMethod, то будет вызван и он',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Spring'
    ),
    20.51
);

