    'Что такое ApplicationContext? Как работает под капотом',
    '**`ApplicationContext`** — это центральный интерфейс контейнера Spring, который управляет жизненным циклом бинов, их зависимостями и предоставляет дополнительные возможности для разработки приложений. Это расширение интерфейса **`BeanFactory`**, добавляющее множество дополнительных функций, таких как обработка событий, поддержка интернационализации и интеграция с AOP.

**Основные функции ApplicationContext**

- **Управление бин-компонентами:**Автоматическое создание, связывание и уничтожение бинов.
- **Инжекция зависимостей:**Поддерживает механизмы Dependency Injection (DI).
- **Обработка событий:**Поддерживает публикацию и прослушивание событий (например, ContextRefreshedEvent).
- **Интернационализация:**Предоставляет механизмы для работы с сообщениями и локалями.
- **Интеграция с AOP:**Позволяет внедрять аспекты в приложение.`import org.springframework.context.ApplicationContext;

import org.springframework.context.annotation.AnnotationConfigApplicationContext;

public class MyApp {

public static void main(String[] args) {

ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);

MyBean myBean = context.getBean(MyBean.class);

myBean.doSomething();

}

}

``читает конфигурацию

