**Как хранить пароль в Spring Security?**

- Хэширование с помощью BCrypt - Spring Security предоставляет поддержку алгоритма BCrypt, который подходит для хэширования паролей`    @Bean

public PasswordEncoder passwordEncoder() {

return new BCryptPasswordEncoder();

}

`При сохранении пароля:

`    @Autowired

private PasswordEncoder passwordEncoder;

public void saveUser(String rawPassword) {

String hashedPassword = passwordEncoder.encode(rawPassword);

// Сохранение hashedPassword в базе данных

}

`
- **Проверка пароля** - при аутентификации введённый пароль сравнивается с хэшированным значением в базе данных`boolean matches = passwordEncoder.matches(rawPassword, hashedPassword);

`**Почему BCrypt?**

- **Защита от атак с помощью “радужных таблиц”** - BCrypt автоматически добавляет случайную “соль” к каждому паролю, чтобы одинаковые пароли имели разные хэши
- **Замедление** - BCrypt есть возможность настройки сложности (work factor), что увеличивает время вычисления хэша, усложняя атакиСравнение с другими современными алгоритмами хэширования

