    'Виды proxy в Spring',
    'Spring использует динамическое проксирование для создания AOP-обёрток над бинами

**Тип Proxy****Описание****Как создается?****JDK Dynamic Proxy**Использует `java.lang.reflect.Proxy`Для интерфейсов**CGLIB Proxy**Использует `net.sf.cglib.proxy`Для классов**AspectJ Proxy**Используется в **Spring AOP**Нужно доп. подключение**JDK Dynamic Proxy (`java.lang.reflect.Proxy`)**

- Используется **только для интерфейсов**.
- Создает прокси-класс, который реализует интерфейс.`public interface Service {

void doWork();

}

public class ServiceImpl implements Service {

public void doWork() {

...

}

}

`Создание динамического прокси вручную:

`Service proxy = (Service) Proxy.newProxyInstance(

Service.class.getClassLoader(),

new Class[]{Service.class},

(proxyObj, method, args) -> {

System.out.println("Логирование перед вызовом метода...");

return method.invoke(new ServiceImpl(), args);

}

);

proxy.doWork();

`**CGLIB Proxy (`net.sf.cglib.proxy`)**

- Используется **для классов** (даже если нет интерфейса).
- Создает **подкласс** оригинального класса`class UserService {}

class UserService$$EnhancerBySpring extends UserService {}

`Создание CGLIB-прокси вручную:

`Enhancer enhancer = new Enhancer();

enhancer.setSuperclass(Service.class);

enhancer.setCallback((MethodInterceptor) (obj, method, args, proxy) -> {

System.out.println("Логирование перед вызовом метода...");

return proxy.invokeSuper(obj, args);

});

Service proxy = (Service) enhancer.create();

proxy.doWork();

`Нельзя проксировать:

- `final` классы
- `final` методы
- `private` методы**CGLIB vs Dynamic Proxy**

**Функция****JDK Dynamic Proxy****CGLIB Proxy****Где работает?**Только с интерфейсамиРаботает с классами**Как создается?**`java.lang.reflect.Proxy``net.sf.cglib.proxy.Enhancer`**Наследование**Нельзя наследовать логику классаСоздает подкласс**Производительность**Чуть быстрееНемного медленнееHibernate (а значит и Spring Data JPA), Mockito и сам Spring (в немногочисленных случаях) использует более современный ByteBuddy. Эта библиотека объединяет возможности обоих видов прокси + дополняет их возможность изменения (enhance) уже скомпилированного байткода.

