    '@Lookup',
    '`@Lookup` - это аннотация в Spring, позволяющая в `singleton`-бине получать новый экземпляр `prototype`-бина при каждом вызове метода. Без `@Lookup` при внедрении `prototype`-бина в `singleton` он создаётся только один раз.

**Как это работает**

- Помечаешь метод в singleton-классе аннотацией `@Lookup`
- Spring динамически переопределяет этот метод (через CGLIB)
- При каждом вызове метода Spring запрашивает новый `prototype`-бин из контекста.`@Component

@Scope("prototype")

public class PrototypeBean {

public void doSomething() {

System.out.println("PrototypeBean: " + this);

}

}

@Component

public abstract class SingletonBean {

public void process() {

// Каждый раз получаем новый экземпляр PrototypeBean

PrototypeBean prototypeBean = getPrototypeBean();

prototypeBean.doSomething();

}

@Lookup

protected abstract PrototypeBean getPrototypeBean();

}

`**Зачем нужно?**

- Когда в `singleton`-бине надо часто создавать `prototype`-объекты
- Чтобы не использовать вручную `ApplicationContext.getBean()`
- Для избежания утечек памяти (прототипы не живут вечно внутри синглтона)',
