VALUES (
    gen_random_uuid(),
    'Как устроен Spring Security',
    'Фреймворк для аутентификации и авторизации. Работает как цепочка фильтров (Servlet Filters), которая перехватывает каждый запрос.

**Основные компоненты**

- **SecurityFilterChain** - набор фильтров, через которые проходит каждый запрос. Примеры фильтров:

- `UsernamePasswordAuthenticationFilter` (логин/пароль)

- `BearerTokenAuthenticationFilter` (JWT токен)
- **Authentication** - объект, представляющий пользователя после входа:

- `principal` (сам пользователь, чаще `UserDetails`)

- `credentials` (пароль или токен)

- `authorities` (роли/права)
- **AuthenticationManager** - точка входа для проверки логина/пароля или токена, делегирует проверку в **AuthenticationProvider**
- **AuthenticationProvider** - конкретная логика проверки (например, сверка пароля с БД)
- **UserDetailsService** - загружает данные пользователя (по имени/почте), возвращает объект `UserDetails` с логином, паролем и ролями
- **Authorization** - после входа система проверяет роли/права. Используются аннотации:

- `@PreAuthorize("hasRole(''ADMIN'')")`

- `@Secured("ROLE_USER")`**Поток обработки запроса**

- Запрос приходит в приложение
- Проходит через **SecurityFilterChain**
- Фильтр (например, `UsernamePasswordAuthenticationFilter`) пытается аутентифицировать
- `AuthenticationManager` вызывает `AuthenticationProvider`
- `UserDetailsService` загружает пользователя, сверяет пароль
- Если успех, создаётся `Authentication`, кладётся в **SecurityContext**
- Далее проверяется авторизация (права/роли)
- Контроллер получает запрос**Пример конфигурации (новый стиль, Spring Security 5.7+)

`@Configuration

@EnableWebSecurity

public class SecurityConfig {

@Bean

public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

http

.authorizeHttpRequests(auth -> auth

.requestMatchers("/admin/**").hasRole("ADMIN")

.anyRequest().authenticated()

)

.formLogin(withDefaults())   // логин/пароль форма

.httpBasic(withDefaults()); // базовая авторизация

return http.build();

}

@Bean

public UserDetailsService users() {

UserDetails user = User.withUsername("user")

.password("{noop}password") // {noop} = без шифрования

.roles("USER")

.build();

return new InMemoryUserDetailsManager(user);

}

}

