- **Factory:**

`BeanFactory` - реализация фабричного паттерна для управления созданием и инициализацией бинов

`MyBean myBean = context.getBean(MyBean.class);`
- **Proxy** используется для аспектов (AOP), например, для логирования, транзакций или кэширования
- **Observer** - события, такие как `ContextRefreshedEvent`, используются для уведомления бинов о состоянии контекста

`@Component

public class MyEventListener implements ApplicationListener<ContextRefreshedEvent> {

@Override

public void onApplicationEvent(ContextRefreshedEvent event) {

System.out.println("Context Refreshed!");

}

}

`
- **Strategy** - разные реализации интерфейсов используются в зависимости от ситуации. Например, `PlatformTransactionManager` имеет реализации для JPA, JDBC и Hibernate

`@Bean

public PlatformTransactionManager transactionManager(EntityManagerFactory emf) {

return new JpaTransactionManager(emf);

}

