VALUES (
    gen_random_uuid(),
    'GET vs POST',
    '**Критерий****GET****POST****Назначение**Получение данныхСоздание или изменение данных**Передача данных**Данные передаются в URL (в строке запроса)Данные передаются в теле (body) HTTP-запроса**Безопасность**Менее безопасный (данные видны в URL и логах сервера)Более безопасный (данные не видны в URL)**Идемпотентность**ИдемпотентенНе идемпотентен**Кэширование**Поддерживается браузерами и прокси-серверамиНе поддерживается кэширование по умолчанию**Ограничение на длину**Ограничения на длину строки URL зависят от браузераОграничения на длину тела запроса обычно отсутствуют**Пример использования**Поиск данных, отображение страницОтправка форм, создание ресурсов, изменение данных**Почему для конфиденциальных данных рекомендуется использовать POST, а не GET запросы**

- **Безопасность** - в GET-запросе данные передаются в URL, который может быть виден в истории браузера, логах сервера и прокси, в POST-запросе данные передаются в теле запроса, что снижает риск случайной утечки
- **Ограничения длины** - длина URL в GET ограничена браузерами или серверами, поэтому большие объемы данных (например, конфиденциальные формы) могут не пройти
- **Кэширование** - GET-запросы могут быть кэшированы прокси-серверами или браузерами, что нежелательно для конфиденциальной информации**Можем ли всегда использовать только POST и не работать с GET?**

Теоретически - да, но это нарушает принципы REST и архитектуру веб-приложений:

- **REST-принципы** - GET предназначен для получения данных, POST - для создания. Использование POST для всех операций затрудняет понимание и поддержку API
- **Оптимизация и кэширование** - GET запросы могут быть кэшированы, что ускоряет работу. POST запросы не кэшируются по умолчанию
- **Поисковые системы и SEO** - GET используется для индексации страниц. Если использовать только POST, страницы не попадут в поисковую выдачу**Можем ли с помощью GET создать ресурс? Есть ли технические ограничения?**

- **Технические ограничения** - с точки зрения HTTP-протокола GET не должен создавать ресурсы. Но технически сервер может обрабатывать GET запросы так, чтобы они изменяли данные (например, создавали ресурс)
- **Практика** - создание или изменение ресурсов через GET нарушает идемпотентность и может вызвать проблемы с кэшированием и повторными запросами**Почему решили из метода GET убрать body?**

- **Неопределённое поведение** - семантика GET подразумевает только получение данных. Тело запроса не является обязательной частью этой семантики, поэтому серверы могут игнорировать его
- **Совместимость** - многие прокси-серверы, фреймворки и библиотеки не поддерживают body в GET, что могло бы привести к проблемам совместимости.
- **Простота и идемпотентность** - GET-запросы считаются идемпотентными и безопасными. Наличие тела могло бы изменить эту концепцию, создавая больше путаницы',
