VALUES (
    gen_random_uuid(),
    'Из чего состоит JSON Web Token?',
    'JWT (JSON Web Token) - это стандартный способ передачи информации в компактном формате (JSON) с подписью для обеспечения его целостности и подлинности. Используется для авторизации, передачи данных между клиентом и сервером

**Из чего состоит JWT?**

JWT состоит из трех частей, разделенных точками (`.`):

`<Header>.<Payload>.<Signature>`
- **Header (заголовок)** - содержит метаинформацию о токене:Алгоритм подписи (например, HMAC SHA256, RSA).
- Тип токена (`JWT`)

Пример:`{

"alg": "HS256",

"typ": "JWT"

}

`
- **Payload (полезная нагрузка)** - содержит данные (как правило о пользователе) - клеймы, которые нужно передать. Может включать:**зарезервированные клеймы:** - стандартные поля, такие как `iss` (издатель), `exp` (время истечения), `sub` (субъект) и некоторые другие
- **пользовательские клеймы** - любые данные, такие как роль пользователя, идентификатор и т.д.

Пример:`{

"sub": "1234567890",

"name": "John Doe",

"admin": true

}

`
- **Signature (подпись)** - нужна для подписи токена, чтобы можно было проверить его подлинность. Формируется с использованием заголовка, полезной нагрузки и секретного ключа (или приватного ключа в случае асимметричного алгоритма подписи)

Пример формулы:`HMACSHA256(

base64UrlEncode(header) + "." + base64UrlEncode(payload),

secret

)`Пример JWT:

`eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiYWRtaW4iOnRydWV9.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c`
- Header - `eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9`
- Payload - `eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiYWRtaW4iOnRydWV9`
- Signature - `SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c`',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'WEB'
    ),
    0.96
);

