VALUES (
    gen_random_uuid(),
    'За что отвечают Cookie/куки?',
    'Cookie - это небольшой файл с данными, который браузер сохраняет от имени веб-сайта. Они передаются между клиентом и сервером через заголовки HTTP

**Основные задачи Cookie**

- **Аутентификация** - хранение сессии пользователя (`JSESSIONID`, `session_token`)
- **Персонализация** - запоминание настроек (язык, тема сайта)
- **Трекинг и аналитика** - сбор данных о пользователях (Google Analytics)
- **Сохранение корзины** - хранение товаров в интернет-магазине**Как работает Cookie?**

- Сервер отправляет Cookie клиенту (браузеру)`Set-Cookie: session_id=abc123; HttpOnly; Secure; Max-Age=3600`
- Клиент сохраняет Cookie и отправляет их при каждом запросе`Cookie: session_id=abc123`
- Сервер проверяет Cookie и принимает решение (например, авторизация)**Виды Cookie**

**Тип Cookie****Описание****Session Cookie**Удаляются после закрытия браузера**Persistent Cookie**Хранятся определенное время (`Max-Age`, `Expires`)**HttpOnly Cookie**Доступны только серверу (JS не может прочитать)**Secure Cookie**Отправляются только по HTTPS**SameSite Cookie**Защита от CSRF (можно ограничить передачу)**Пример Set-Cookie с атрибутами**

`Set-Cookie: user=Alice; Expires=Wed, 21 Oct 2025 07:28:00 GMT; Secure; HttpOnly; SameSite=Strict`',
