    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Отличия POST, PUT, PATCH',
    '**Метод****Назначение****Идемпотентность****Тело запроса****Пример использования****POST**Создание нового ресурса или выполнение некой операции❌ НеидемпотентенПолные данные для создания`POST /users` (создать нового пользователя)**PUT**Полная замена ресурса (или создание, если не существует)✅ ИдемпотентенПолные данные для ресурса`PUT /users/123` (заменить пользователя с ID=123)**PATCH**Частичное обновление ресурса❌ Неидемпотентен (по стандарту)Данные с изменяемыми полями`PATCH /users/123` (обновить только email пользователя)**Дополнительные пояснения:**

- **POST**:

Используется для **создания** или запуска **операций**, которые могут изменять состояние на сервере.
- Повторный вызов `POST` может приводить к **дублированию** ресурсов (неидемпотентность).
- **PUT**:

Обычно подразумевает **полное** обновление ресурса по указанному URI.
- **Идемпотентность**: повторный вызов с тем же телом запроса не изменит результат (если ресурс уже существует).
- **PATCH**:

Позволяет **частично обновлять** ресурс (передаём только изменяемые поля).
- **Часто** не считается идемпотентным, так как повторное применение `PATCH` может привести к другим изменениям, но многое зависит от реализации.Таким образом, **POST** чаще всего используется для **создания**, **PUT** – для **полной замены** (или создания, если ресурс отсутствует), а **PATCH** – для **частичного обновления**.',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'WEB'
    ),
    3.53
);

