VALUES (
    gen_random_uuid(),
    'Что такое Producer и что такое Consumer?',
    'Producer (производитель) - отправитель сообщений

Consumer (потребитель) - получатель сообщений

**Что даст увеличение количества консьюмеров?**

Увеличение числа консьюмеров в группе (consumer group) позволяет ускорить обработку данных, т.к. каждый консьюмер будет обрабатывать свою партицию одновременно с остальными консьюмерами. Также это позволяет распределить ответственность между разными компонентами.

Если консьюмеров меньше, чем партиций - они будут распределены через Round-Robin (или кастомный метод). Если консьюмеров больше, чем партиций - какие-то из консьюмеров будут простаивать

**Пример**

Топик с 4 партициями

- Если в группе 2 потребителя, то каждый будет обрабатывать 2 партиции
- Если в группе 3 потребителя, то (по дефолту) один из них будет обрабатывать 2 партиции
- Если в группе 4 потребителя, каждый получит по 1 партиции
- Если в группе 5 потребителей, один из них останется без работы',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Брокеры сообщений'
    ),
    1.6
);

