    'Продюсер определяет, в какой раздел отправить сообщение, используя следующие подходы:

- Явное указание партиции - продюсер может явно указать, в какую партицию отправить сообщение
- Выбор партиции на основании алгоритма (без явного указания)

Если сообщение содержит ключ, Kafka использует хеширование ключа для выбора раздела. Это гарантирует, что все сообщения с одинаковым ключом будут попадать в один раздел
- Если ключ и явное указание партиции отсутствуют, используется стратегия Sticky Partitioning - все сообщения пишутся в одну партицию до достижения `batch.size` (размер батча в байтах, по умолчанию равен 16384)*Примечание. Распространено заблуждение, что **по умолчанию** Kafka-продюсер распределяет сообщения по партициям, используя стратегию Round-Robin. Однако с версии 2.4 это не так (

). Выбрать стратегию Round-Robin можно при помощи явного указания*

`spring:

kafka:

producer:

properties:

partitioner.class:

org.apache.kafka.clients.producer.RoundRobinPartitioner

`
- **Кастомный алгоритм** - продюсер может реализовать собственную логику распределения сообщений по разделам (реализовав интерфейс `Partitioner`)',
