    'Pull и push модели, в чём разница?',
    '**Pull-модель (”вытягивание”)** - клиент запрашивает данные у сервера (или брокера). Пример - консьюмеры в Kafka запрашивают данные у брокеров

**Преимущества:**

- клиент контролирует скорость обработки, что особенно важно при высокой нагрузке.
- легко обрабатывать данные на уровне клиента

**Недостатки:**
- может возникнуть задержка, если клиент редко запрашивает данные
- требует постоянного запроса данных**Push (”проталкивание”)** - сервер отправляет данные клиенту по мере их поступления.

Пример: WebSocket, Firebase Cloud Messaging.

**Преимущества:**

- меньшая задержка - данные сразу отправляются клиенту
- удобно для реального времени (например, уведомления)

**Недостатки:**
- клиент может быть перегружен большим потоком данных
