Параметр `enable.idempotence` в конфигурации продюсера позволяет Kafka отслеживать дубликаты сообщений с использованием уникального идентификатора производителя (**Producer ID**) и последовательного номера сообщения (**Sequence Number**)`Properties props = new Properties();

