**Использование:**

- потребители используют offset, чтобы отслеживать, какие сообщения уже были обработаны
- offset хранится в Kafka (по умолчанию в специальном топике `__consumer_offsets`) или в клиенте**Виды управления:**

- Автоматическое управление (auto commit) - Kafka сама обновляет offset после чтения сообщения, настраивается параметром `enable.auto.commit=true`
- Ручное управление (manual commit) - потребитель сам обновляет offset после успешной обработки сообщения, используется для большей надежности`	consumer.commitSync(); // Обновление offset синхронно

consumer.commitAsync(); // Обновление offset асинхронно

`',
