VALUES (
    gen_random_uuid(),
    'Основные аннотации в тестировании',
    'Основные аннотации JUnit 5

АннотацияНазначение`@Test`Обозначает метод как тестовый`@BeforeEach`Метод выполняется **перед каждым** тестом`@AfterEach`Метод выполняется **после каждого** теста`@BeforeAll`Выполняется **один раз перед всеми тестами** (должен быть `static`)`@AfterAll`Выполняется **один раз после всех тестов** (должен быть `static`)`@DisplayName`Назначает удобное имя тесту, отображается в отчётах`@Disabled`Отключает тест (временно пропускает)`@Nested`Позволяет группировать тесты во вложенные классы`@Tag`Помечает тест определённым тегом (удобно для фильтрации)`@ParameterizedTest`Используется для **параметризованных тестов** (с разными входами)`@Order`Порядок выполнения тестовых методов`@TestMethodOrder`Стратегия определения последовательности запуска тестовых методов для всего класса`import org.junit.jupiter.api.*;

import org.junit.jupiter.params.ParameterizedTest;

import org.junit.jupiter.params.provider.ValueSource;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)

public class UserServiceTest {

@BeforeAll

static void initAll() {

System.out.println("Before all tests");

}

@BeforeEach

void init() {

System.out.println("Before each test");

}

@Order(3)

@Test

@DisplayName("Проверка регистрации пользователя")

void testUserRegistration() {

Assertions.assertEquals(2, 1 + 1);

}

@Order(1)

@Test

@Disabled("Временно отключен")

void disabledTest() {

Assertions.fail("Этот тест не будет выполнен");

}

@Order(2)

@ParameterizedTest

@ValueSource(strings = {"admin", "user", "guest"})

void testRoles(String role) {

Assertions.assertTrue(role.length() > 0);

}

@Nested

class NestedTestClass{

@Test

@Tag("any")

void nestedTest() {

Assertions.assertTrue("1" == "1");

}

}

@AfterEach

void tearDown() {

System.out.println("After each test");

}

@AfterAll

static void tearDownAll() {

System.out.println("After all tests");

}

}

