INSERT INTO cards (
    card_id,
    question,
    answer,
    desk_id,
    meet_chance
)
VALUES (
    gen_random_uuid(),
    'Обычное программирование vs реактивщина',
    '- **Императивное (обычное) программирование**В императивном стиле вы **пошагово** описываете, как именно программа должна добиться результата:

`// Пример: читаем список чисел, фильтруем, суммируем

List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);

int sum = 0;

for (Integer n : numbers) {

if (n % 2 == 0) {

sum += n;

}

}

System.out.println("Sum of evens = " + sum);

`
- **Последовательность шагов**: `создать → пройти по элементам → проверить → накопить результат`.
- Код **жестко синхронный**: поток выполнения блокируется на каждом шаге.
- Легко понять, но сложно масштабировать под асинхронные/событийные задачи.
- **Реактивное программирование**Реактивщина (Reactive Programming) ориентирована на **потоки событий** и **асинхронную обработку** — вы описываете **что** должно происходить при поступлении новых данных:

`import reactor.core.publisher.Flux;

public class ReactiveExample {

public static void main(String[] args) {

Flux<Integer> numbers = Flux.just(1, 2, 3, 4, 5);

numbers

.filter(n -> n % 2 == 0)    // пропускаем только чётные

.reduce(Integer::sum)       // аккумулируем сумму

.subscribe(sum ->            // при готовности выводим результат

System.out.println("Sum of evens = " + sum)

);

}

}

`Здесь мы:

- **Создаём поток** (`Flux.just(...)`).
- **Прописываем операторы** (`filter`, `reduce`) — они не выполняются сразу, а образуют конвейер.
- **Подписываемся** (`subscribe`), и тогда данные «текут» через конвейер **асинхронно** или **постепенно**.**Ключевые особенности реактивного стиля**

- **Push‑модель**: данные «пушатся» в конвейер, а вы описываете, что делать с каждым элементом.
- **Не блокируется**: можно легко работать с высокой нагрузкой, обрабатывать сетевые ответы, таймеры и т. д.
- **Backpressure**: реактивные библиотеки умеют регулировать скорость потока, чтобы потребитель не утонул в данных.
- **Композиция**: операторы (`map`, `flatMap`, `buffer`, `window` и т. д.) позволяют строить сложные асинхронные сценарии декларативно.
- **Пример: HTTP‑запросы****Императивно (RestTemplate)**

`RestTemplate rest = new RestTemplate();

String body = rest.getForObject("https://api.example.com/data", String.class);

System.out.println("Response: " + body);

`Этот вызов **блокирует** текущий поток до получения ответа.

**Реактивно (WebClient)**

`WebClient client = WebClient.create("https://api.example.com");

client.get()

.uri("/data")

.retrieve()

.bodyToMono(String.class)  // Mono<String> — поток из одного элемента

.subscribe(body -> System.out.println("Response: " + body));

`
- `retrieve().bodyToMono(...)` возвращает `Mono<String>`, не блокируя поток.
- Легко добавлять таймауты, retry, комбинировать несколько запросов через `zip`, `flatMap` и т. д.
- **Когда выбирать что**ПодходКогда подходитМинусы**Императивный**Простые сценарии, синхронная логика, быстрые PoCСложнее в асинхронных задачах, масштабировании**Реактивный**Высоконагруженные системы, I/O‑операции, event‑drivenКруче порог вхождения, отладка сложнее**Ключевые моменты**

- **Императивный стиль** описывает *как* выполнять шаг за шагом, легко читается для простых задач, но блокирует поток.
- **Реактивный стиль** описывает *что* должно происходить с данными при их поступлении, строит конвейер операторов и поддерживает асинхронность.
- **Push vs Pull**: реактивный код «толкает» события вниз по цепочке, вместо того, чтобы «тянуть» их через циклы.
- **Backpressure** позволяет управлять скоростью обработки, гарантируя стабильную работу под высокой нагрузкой.
- **Композиция операторов** даёт выразительный, декларативный код, но требует привыкания и новых инструментов (Reactor, RxJava).',
    (
        SELECT desk_id
        FROM desks
        WHERE name = 'Другое'
    ),
    2.24
);

